"""Stateful streaming dedupe fixture."""

from __future__ import annotations

from copy import deepcopy
from typing import Dict, Any


class WatermarkDeduper:
    """Deduplicate events by event_id with watermark and TTL eviction."""

    def __init__(self, *, allowed_lateness: int = 0, ttl: int = 100) -> None:
        if allowed_lateness < 0:
            raise ValueError("allowed_lateness must be >= 0")
        if ttl < 1:
            raise ValueError("ttl must be >= 1")
        self.allowed_lateness = allowed_lateness
        self.ttl = ttl
        # watermark starts at negative infinity
        self._watermark: float = float("-inf")
        # maps event_id -> last seen event_time (for retained/non-evicted events)
        self._seen: Dict[str, int] = {}

    def _validate_event(self, event: dict) -> None:
        if not isinstance(event.get("event_id"), str):
            raise ValueError("event_id must be a string")
        if not isinstance(event.get("event_time"), int):
            raise ValueError("event_time must be an integer")

    def _evict(self) -> None:
        """Evict event IDs last seen at or before watermark - ttl."""
        if self._watermark == float("-inf"):
            return
        eviction_threshold = self._watermark - self.ttl
        to_evict = [eid for eid, t in self._seen.items() if t <= eviction_threshold]
        for eid in to_evict:
            del self._seen[eid]

    def process(self, events: list[dict[str, object]]) -> list[dict[str, object]]:
        emitted: list[dict[str, object]] = []
        for event in events:
            self._validate_event(event)
            event_id: str = event["event_id"]  # type: ignore[assignment]
            event_time: int = event["event_time"]  # type: ignore[assignment]

            # Check if event is late: event_time <= watermark means late
            if self._watermark != float("-inf") and event_time <= self._watermark:
                # Late event: drop without changing state
                continue

            # Check for duplicate
            if event_id in self._seen:
                # Update last seen time for this id (it's a non-late duplicate)
                # Don't emit, but we should update last seen time? 
                # Spec says: "its event_id has not already been seen in retained state"
                # So we don't emit it. But do we update the last seen time?
                # The spec says retained dedupe state is not changed for late events,
                # but for non-late duplicates, we still process them (just don't emit).
                # We should update last_seen time to keep the ID alive longer.
                self._seen[event_id] = max(self._seen[event_id], event_time)
                # Advance watermark
                new_watermark = event_time - self.allowed_lateness
                if self._watermark == float("-inf") or new_watermark > self._watermark:
                    self._watermark = new_watermark
                    self._evict()
                continue

            # Non-late, non-duplicate: emit
            self._seen[event_id] = event_time
            emitted.append(deepcopy(event))

            # Advance watermark
            new_watermark = event_time - self.allowed_lateness
            if self._watermark == float("-inf") or new_watermark > self._watermark:
                self._watermark = new_watermark
                self._evict()

        return emitted

    def snapshot(self) -> dict[str, object]:
        return {
            "allowed_lateness": self.allowed_lateness,
            "ttl": self.ttl,
            "watermark": self._watermark,
            "seen": {k: v for k, v in self._seen.items()},
        }

    def restore(self, snapshot: dict[str, object]) -> None:
        self.allowed_lateness = int(snapshot["allowed_lateness"])
        self.ttl = int(snapshot["ttl"])
        watermark = snapshot["watermark"]
        if watermark == float("-inf") or watermark == "-inf":
            self._watermark = float("-inf")
        else:
            self._watermark = float(watermark)  # type: ignore[arg-type]
        seen = snapshot["seen"]
        if isinstance(seen, dict):
            self._seen = {str(k): int(v) for k, v in seen.items()}
        else:
            # legacy list format fallback
            self._seen = {}

    def state_size(self) -> int:
        return len(self._seen)
